package com.flexi.jarvis.network

import android.util.Base64
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URL

data class GeneratedSpeech(
    val pcm16: ByteArray,
    val sampleRate: Int
)

/** Authenticated client for natural Gemini TTS audio generated by the Cloudflare Worker. */
class GeminiTtsApi(
    private val baseUrl: String,
    private val accessTokenProvider: suspend () -> String?
) {
    suspend fun synthesize(
        text: String,
        voice: String = "Charon"
    ): GeneratedSpeech = withContext(Dispatchers.IO) {
        require(text.isNotBlank()) { "There is no response to speak." }
        require(text.length <= 10_000) { "The response is too long to speak in one request." }

        val endpoint = baseUrl.trim().trimEnd('/')
        require(endpoint.startsWith("https://")) { "The speech service URL is not configured." }

        val token = accessTokenProvider()
            ?: throw IOException("Please sign in again before using JARVIS voice.")

        val body = JSONObject()
            .put("text", text)
            .put("voice", voice)

        val connection = URL("$endpoint/tts").openConnection() as HttpURLConnection
        try {
            connection.requestMethod = "POST"
            connection.connectTimeout = 20_000
            connection.readTimeout = 120_000
            connection.doOutput = true
            connection.useCaches = false
            connection.setRequestProperty("Authorization", "Bearer $token")
            connection.setRequestProperty("Content-Type", "application/json; charset=utf-8")
            connection.setRequestProperty("Accept", "application/json")

            connection.outputStream.use {
                it.write(body.toString().toByteArray(Charsets.UTF_8))
            }

            val status = connection.responseCode
            val stream = if (status in 200..299) connection.inputStream else connection.errorStream
            val raw = stream?.bufferedReader()?.use { it.readText() }.orEmpty()
            val json = runCatching { JSONObject(raw) }.getOrElse { JSONObject() }

            if (status !in 200..299) {
                val detail = json.optString("detail")
                    .ifBlank { "Natural speech generation failed (HTTP $status)." }
                throw IOException(detail.take(500))
            }

            val encoded = json.optString("audioBase64")
            if (encoded.isBlank()) throw IOException("The speech service returned no audio.")

            val pcm = try {
                Base64.decode(encoded, Base64.DEFAULT)
            } catch (_: IllegalArgumentException) {
                throw IOException("The speech service returned invalid audio data.")
            }
            if (pcm.isEmpty()) throw IOException("The generated speech audio was empty.")

            val mime = json.optString("mimeType", "audio/pcm;rate=24000")
            val sampleRate = Regex("rate=(\\d+)")
                .find(mime)
                ?.groupValues
                ?.getOrNull(1)
                ?.toIntOrNull()
                ?: 24_000

            GeneratedSpeech(pcm, sampleRate)
        } finally {
            connection.disconnect()
        }
    }
}
